 public sealed partial class MobileGameApp {
  void WorldStrategy(){var a=empire.Snapshot;var r=empire.ForecastCity();Base("city-strategy");Studio.Box(root,"Business strategy heading",18,12,684,218,FlatUI.Hex("#0A285AF5"));Studio.Header(root,"GROWTH HAS COSTS AND CONSEQUENCES","Business strategy",CityMoney(r.OperatingNet)+" OPERATING MARGIN · "+CityMoney(r.LoanDue)+" DEBT DUE",WorldDesk);string[] names={"COMPARE FINANCING","SUPPLIERS & SPONSORS","POWER & UTILITY CAPACITY","BUY TIMBER & STEEL","INSPECT MY BUSINESSES"};Action[] actions={()=>WorldFinance(WorldStrategy),WorldAgreements,WorldUtilities,()=>WorldMaterialsMarket(),PermanentCityScreen};for(int i=0;i<names.Length;i++)Studio.Button(root,names[i],38,290+i*150,644,115,actions[i],i==0);Studio.Label(root,"Marketing and employees live inside each business.\nA construction company supplies materials; developing it adds an earned builder.\n\nPrices,capacity,stock,wages and financing feed the same next-day margin. A bigger city is useful when its economics work.",44,1065,632,180,25,Studio.Text,TextAlignmentOptions.Center);Probe();}
  void WorldLandChoices(){var city=empire.Snapshot.City;var m=Studio.Modal(root,"GROW THE SAME CITY",PermanentCityScreen);Studio.Image(m,"district0",44,220,632,330);Studio.Label(m,"Add land beside your city.\nYour buildings and history stay.\n\nOwned land: "+city.Width+" × "+city.Height+"\nTwo new rows or columns: "+CityMoney(city.Width*city.Height*10L)+"\n\nPan and zoom to review the neighborhood.",44,610,632,330,29,Studio.Text,TextAlignmentOptions.Center);Studio.Button(m,"EXPAND EAST",44,1000,632,90,()=>WorldExpansion(true),true);Studio.Button(m,"EXPAND SOUTH",44,1120,632,90,()=>WorldExpansion(false));}
  void WorldMaterialsMarket(){var m=Studio.Modal(root,"CONSTRUCTION MATERIALS",WorldStrategy);Studio.Image(m,"warehouse",250,200,220,220);Studio.Label(m,"Construction uses real stock as well as cash and a builder. Farms supply timber; a construction company can supply timber and steel.\n\nThe market is an earned-cash alternative,with published prices. Orders are charged and saved exactly once.\n\nCurrent stock\nWOOD "+empire.Snapshot.Economy.Amount("WOOD")+" · STEEL "+empire.Snapshot.Economy.Amount("STEEL"),44,470,632,420,29,Studio.Text,TextAlignmentOptions.Center);Studio.Button(m,"TIMBER · INSPECT SOURCES",44,970,632,100,()=>WorldMaterial("WOOD",5,WorldMaterialsMarket));Studio.Button(m,"STEEL · INSPECT SOURCES",44,1100,632,100,()=>WorldMaterial("STEEL",5,WorldMaterialsMarket),true);}
  void DrawOwnedCityMiniature(RectTransform parent,CityState city){var frame=Studio.Box(parent,"Your actual city",38,240,644,300,FlatUI.Hex("#123765"));var inset=FlatUI.Rect(frame,"City miniature inset",26,45,668,1190);var grid=FlatUI.Panel(inset,"Miniature surface",0,0,720,1280,FlatUI.Hex("#233C5A"));var fit=grid.gameObject.AddComponent<UnityEngine.UI.AspectRatioFitter>();fit.aspectMode=UnityEngine.UI.AspectRatioFitter.AspectMode.FitInParent;fit.aspectRatio=city.Width/(float)city.Height;for(int y=0;y<city.Height;y++)for(int x=0;x<city.Width;x++){var p=city.Properties.FirstOrDefault(b=>b.X==x&&b.Y==y);var tile=FlatUI.Rect(grid,"Miniature plot",x*720f/city.Width,y*1280f/city.Height,720f/city.Width,1280f/city.Height);Studio.Image(tile,"V3/plot",40,65,640,1150,p==null?new Color(.8f,.95f,.7f,.85f):Color.white);if(p!=null)PropertyArt(tile,p,28,10,664,1180);}}

